-- Generated by pwc2dbt from mapping m_FL_JS_MARTS_CORE, target instance CUSTOMERS. Do not edit.

with

sq_stg_orders2 as (

    select
        cast(stg_orders2.order_id as varchar) as order_id,
        cast(stg_orders2.customer_id as varchar) as customer_id,
        cast(stg_orders2.ordered_at_day as timestamp) as ordered_at_day,
        cast(stg_orders2.subtotal as double) as subtotal,
        cast(stg_orders2.tax_paid as double) as tax_paid,
        cast(stg_orders2.order_total as double) as order_total
    from {{ ref('stg_orders') }} as stg_orders2

),

agg_orders_by_customer as (

    select
        sq_stg_orders2.customer_id as customer_id,
        count(sq_stg_orders2.order_id) as lifetime_orders,
        min(sq_stg_orders2.ordered_at_day) as first_order_date,
        max(sq_stg_orders2.ordered_at_day) as last_order_date,
        sum(sq_stg_orders2.order_total) as lifetime_spend,
        sum(sq_stg_orders2.subtotal) as lifetime_spend_pretax,
        sum(sq_stg_orders2.tax_paid) as lifetime_tax_paid
    from sq_stg_orders2
    group by sq_stg_orders2.customer_id

),

sq_stg_customers as (

    select
        cast(stg_customers.customer_id as varchar) as customer_id,
        cast(stg_customers.customer_name as varchar) as customer_name
    from {{ ref('stg_customers') }} as stg_customers

),

jnr_customers_orders as (

    select
        master.customer_id as customer_id,
        master.customer_name as customer_name,
        detail.lifetime_orders as lifetime_orders,
        detail.first_order_date as first_order_date,
        detail.last_order_date as last_order_date,
        detail.lifetime_spend as lifetime_spend,
        detail.lifetime_spend_pretax as lifetime_spend_pretax,
        detail.lifetime_tax_paid as lifetime_tax_paid
    from agg_orders_by_customer as detail
    left join sq_stg_customers as master
        on master.customer_id = detail.customer_id

),

exp_customer_metrics as (

    select
        jnr_customers_orders.customer_id as customer_id,
        jnr_customers_orders.customer_name as customer_name,
        case when (jnr_customers_orders.lifetime_orders is null) then 0 else jnr_customers_orders.lifetime_orders end as lifetime_orders_cl,
        jnr_customers_orders.first_order_date as first_order_date,
        jnr_customers_orders.last_order_date as last_order_date,
        case when (jnr_customers_orders.lifetime_spend is null) then 0 else jnr_customers_orders.lifetime_spend end as lifetime_spend_cl,
        case when (jnr_customers_orders.lifetime_spend_pretax is null) then 0 else jnr_customers_orders.lifetime_spend_pretax end as lifetime_spend_pretax_cl,
        case when (jnr_customers_orders.lifetime_tax_paid is null) then 0 else jnr_customers_orders.lifetime_tax_paid end as lifetime_tax_paid_cl,
        case when case when (jnr_customers_orders.lifetime_orders is null) then 0 else jnr_customers_orders.lifetime_orders end > 1 then 'returning' else 'new' end as customer_type
    from jnr_customers_orders

)

select
    cast(exp_customer_metrics.customer_id as varchar) as customer_id,
    cast(exp_customer_metrics.customer_name as varchar) as customer_name,
    cast(exp_customer_metrics.lifetime_orders_cl as double) as lifetime_orders,
    cast(exp_customer_metrics.first_order_date as timestamp) as first_order_date,
    cast(exp_customer_metrics.last_order_date as timestamp) as last_order_date,
    cast(exp_customer_metrics.lifetime_spend_cl as decimal(12,2)) as lifetime_spend,
    cast(exp_customer_metrics.lifetime_spend_pretax_cl as decimal(12,2)) as lifetime_spend_pretax,
    cast(exp_customer_metrics.lifetime_tax_paid_cl as decimal(12,2)) as lifetime_tax_paid,
    cast(exp_customer_metrics.customer_type as varchar) as customer_type
from exp_customer_metrics
